python3 -c 'import json, pathlib, subprocess, sys
payload = {}
try:
    data = sys.stdin.read()
    payload = json.loads(data)
    if not isinstance(payload, dict):
        raise ValueError("hook input must be an object")
    def git(arg):
        return subprocess.check_output(["git", "rev-parse", arg], text=True, stderr=subprocess.DEVNULL, timeout=1).rstrip("\n")
    roots = [pathlib.Path(git("--git-common-dir")).resolve().parent, pathlib.Path(git("--show-toplevel"))]
    script = next(root / "scripts/agora-task.py" for root in roots if (root / "scripts/agora-task.py").is_file())
    result = subprocess.run([sys.executable, str(script), "hook"], input=data, text=True, capture_output=True, timeout=7)
    if result.returncode:
        raise RuntimeError("handler failed")
    output = json.loads(result.stdout)
    if not isinstance(output, dict):
        raise ValueError("handler output must be an object")
except Exception as error:
    output = {"systemMessage": "Agora hook unavailable (" + type(error).__name__ + "). Checks were not completed."}
    if isinstance(payload, dict) and payload.get("hook_event_name") == "PreToolUse" and payload.get("tool_name") == "mcp__codex_apps__github_create_pull_request":
        output["hookSpecificOutput"] = {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Agora hook is unavailable. This restricted method remains denied; use gh pr create."}
print(json.dumps(output))
'

